assignments.value:
={{
(
  $json["Company Size"] == "Large" ? 30 :
  $json["Company Size"] == "Medium (11-50 Employees)" ? 20 : 10
)
+
(
  ["Technology", "Marketing", "Finance"].includes($json["Industry"]) ? 20 : 5
)
+
(
  $json.Email.match(/@(gmail|yahoo|hotmail|outlook)\./i) ? 10 : 20
)
+
(
  $json["Budget Range"] == "High Budget" ? 20 :
  $json["Budget Range"] == "Medium Budget" ? 10 : 5
)
+
(
  $json["Urgency Level"] == "Immediate Need" ? 10 :
  $json["Urgency Level"] == "Within 1 Month" ? 8 : 5
)
}}

parameters.message:
={{
"<h2>New Lead Received</h2>" +
"<p><strong>Name:</strong> " + $json["Full Name"] + "</p>" +
"<p><strong>Email:</strong> " + $json["Business Email Address"] + "</p>" +
"<p><strong>Company:</strong> " + $json["Company Name"] + "</p>" +
"<p><strong>Phone:</strong> " + $json["Phone Number"] + "</p>" +
"<p><strong>Lead Score:</strong> " + $json["Lead Score"] + "</p>" +
"<p><strong>Lead Status:</strong> " + $json["Lead Status"] + "</p>" +
"<p><strong>Received:</strong> " + $now.toFormat("MMMM d, yyyy h:mm a") + "</p>"
}}
